import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long a = sc.nextLong();
        long b = sc.nextLong();
        long c = sc.nextLong();
        long d = sc.nextLong();

        long diff1 = Math.abs((a + b) - (c + d));
        long diff2 = Math.abs((a + c) - (b + d));
        long diff3 = Math.abs((a + d) - (b + c));

        long answer = Math.min(diff1, Math.min(diff2, diff3));

        System.out.println(answer);

        sc.close();
    }
}
